  function restart(){s=NTPC.init(P,inputs());hist=[s];paint()}
  function prime(){const keep=hist,ks=s;const all=NTPC.run(P,inputs(),300);hist=all.slice(-60);s=all[all.length-1];paint();hist=keep;s=ks;paint()}
  function push(n){s=n;hist.push(n);if(hist.length>NTPC.LIMIT+1)hist.shift();paint()}
  function load(i){pi=i;P=PR[i];bps=new Set(P.bp||[]);watches=(P.watch||cfg.watch||[]).slice();SD.free();$("nt").innerHTML=P.note||"";drawInputs();drawCode();s=NTPC.init(P,inputs());hist=[s];prime()}
  $("sel").onchange=()=>load(+$("sel").value);
