/* ===================== BÀI 10 · Chương trình được tạo và chạy thế nào ===================== */
/* ---- công cụ tương tác: chép từ tools/author/nentang/whex.js bởi m03lib.write3 ---- */
/* Bài 10 · Bộ đọc bản ghi Intel HEX (AMTS-FND-002-SIM12, phần chuỗi build nguồn → object → HEX).
   NTHEX: phần TÍNH (engine), hàm thuần, không đụng DOM. Kiểm thử: python3 tests/nentang/ref_m03.py && node tests/nentang/test_m03.js
   (so với tổng kiểm tra tính độc lập bằng Python và với các dòng .ihx do sdld của SDCC 4.2.0 sinh ra thật).
   makeNtHex: phần VẼ, chỉ gọi NTHEX. Định dạng: ':' LL AAAA TT [DD…] CC; CC = bù hai của tổng các byte LL…DD (mod 256).
   Giới hạn: chỉ giải mã từng dòng và vẽ ô nhớ của bản ghi dữ liệu (TT = 00) trong 64 KiB; bản ghi 02/04 (địa chỉ mở rộng)
   chỉ được gọi tên, không cộng vào địa chỉ; không mô phỏng việc ghi flash. */
const NTHEX={
  TYPES:{0:"dữ liệu (data)",1:"kết thúc tệp (end of file)",2:"địa chỉ đoạn mở rộng (extended segment address)",3:"địa chỉ bắt đầu đoạn (start segment address)",4:"địa chỉ tuyến tính mở rộng (extended linear address)",5:"địa chỉ bắt đầu tuyến tính (start linear address)"},
  hx(v,n){return(v>>>0).toString(16).toUpperCase().padStart(n||2,"0")},
  /* tổng kiểm tra của các byte (mảng số 0…255) */
  sum(bytes){let s=0;for(const b of bytes)s=(s+b)&255;return(256-s)&255},
  parse(line){const s=String(line==null?"":line).trim();
    if(!s)return{ok:false,err:"Dòng trống."};
    if(s[0]!==":")return{ok:false,err:"Bản ghi Intel HEX phải bắt đầu bằng dấu hai chấm “:”."};
    const h=s.slice(1);
    if(!/^[0-9A-Fa-f]*$/.test(h))return{ok:false,err:"Sau dấu “:” chỉ được có chữ số hex 0–9, A–F (không dấu cách)."};
    if(h.length%2)return{ok:false,err:`Số chữ số hex sau “:” là ${h.length}, phải là số chẵn (mỗi byte 2 chữ số).`};
    if(h.length<10)return{ok:false,err:"Bản ghi quá ngắn: cần ít nhất LL AAAA TT CC (5 byte)."};
    const B=[];for(let i=0;i<h.length;i+=2)B.push(parseInt(h.slice(i,i+2),16));
    const n=B[0];
    if(B.length!==n+5)return{ok:false,err:`Byte đầu LL = ${NTHEX.hx(n)}H nói có ${n} byte dữ liệu, nhưng dòng có ${B.length-5} byte giữa TT và CC.`};
    const addr=B[1]*256+B[2],type=B[3],data=B.slice(4,4+n),sum=B[4+n],want=NTHEX.sum(B.slice(0,4+n));
    return{ok:true,n,addr,type,data,sum,want,good:sum===want,tname:NTHEX.TYPES[type]||"loại không chuẩn",
      parts:[[":", "f0","dấu bắt đầu"],[h.slice(0,2),"f1","LL: số byte dữ liệu"],[h.slice(2,6),"f2","AAAA: địa chỉ"],[h.slice(6,8),"f3","TT: loại bản ghi"],[h.slice(8,8+2*n),"f4","dữ liệu"],[h.slice(8+2*n),"f5","CC: tổng kiểm tra"]]}},
  make(addr,data,type){const B=[data.length,(addr>>8)&255,addr&255,type||0].concat(data);return":"+B.concat([NTHEX.sum(B)]).map(b=>NTHEX.hx(b)).join("")}
};
function makeNtHex(el,cfg){
  const ID="nhx-"+(cfg.id||"x"),E=window.esc||(s=>String(s));
  el.classList.add("n3-hex");
  el.innerHTML=`<label for="${ID}-in" class="n3-h">Dán một hoặc nhiều dòng của file .hex</label>
   <textarea id="${ID}-in" spellcheck="false" autocomplete="off" rows="3"></textarea>
   <div class="n3-row"><button type="button" class="btn pri" id="${ID}-go">Giải mã</button><button type="button" class="btn" id="${ID}-fix">Tính lại tổng kiểm tra</button>
   <label class="mt-sel"><span>Mẫu</span><select id="${ID}-ex">${cfg.samples.map((s,i)=>`<option value="${i}">${E(s[0])}</option>`).join("")}</select></label></div>
   <div id="${ID}-out" aria-live="polite"></div>`;
  const $=x=>el.querySelector("#"+ID+"-"+x);
  function show(){const lines=$("in").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),mem={};let html="";
    if(!lines.length){$("out").innerHTML='<p class="n3-verdict warn">Chưa có dòng nào.</p>';return}
    lines.slice(0,12).forEach((l,i)=>{const r=NTHEX.parse(l);
      if(!r.ok){html+=`<p class="n3-verdict bad">Dòng ${i+1}: ${E(r.err)}</p>`;return}
      html+=`<p class="n3-hexline">${r.parts.map(p=>`<span class="${p[1]}${p[1]==="f5"&&r.good?" ok":""}" title="${p[2]}">${p[0]}</span>`).join("")}</p>
      <dl><dt>Số byte dữ liệu (LL)</dt><dd>${NTHEX.hx(r.n)}H = ${r.n}</dd><dt>Địa chỉ (AAAA)</dt><dd>${NTHEX.hx(r.addr,4)}H</dd><dt>Loại (TT)</dt><dd>${NTHEX.hx(r.type)}H: ${E(r.tname)}</dd>
      <dt>Dữ liệu</dt><dd>${r.data.length?r.data.map(b=>NTHEX.hx(b)).join(" "):"(không có)"}</dd>
      <dt>Tổng kiểm tra (CC)</dt><dd>ghi ${NTHEX.hx(r.sum)}H · tính lại ${NTHEX.hx(r.want)}H</dd></dl>
      <p class="n3-verdict ${r.good?"ok":"bad"}">Dòng ${i+1}: tổng kiểm tra ${r.good?"đúng":"sai: dòng này đã bị hỏng hoặc gõ nhầm"}.</p>`;
      if(r.good&&r.type===0)r.data.forEach((b,k)=>{mem[r.addr+k]=b})});
    if(lines.length>12)html+=`<p class="mt-cap">Chỉ giải mã 12 dòng đầu.</p>`;
    const ks=Object.keys(mem).map(Number).sort((a,b)=>a-b);
    if(ks.length){const rows={};ks.forEach(a=>{const r=a&~7;(rows[r]=rows[r]||{})[a&7]=mem[a]});
      html+=`<p class="n3-h">Bộ nhớ chương trình sau khi nạp các dòng đúng (8 byte mỗi hàng)</p><div class="n3-mem"><table class="mt-tab"><thead><tr><th scope="col">Địa chỉ</th>${[0,1,2,3,4,5,6,7].map(k=>`<th scope="col">+${k}</th>`).join("")}</tr></thead><tbody>${Object.keys(rows).map(Number).sort((a,b)=>a-b).slice(0,16).map(r=>`<tr><td>${NTHEX.hx(r,4)}H</td>${[0,1,2,3,4,5,6,7].map(k=>`<td${rows[r][k]==null?' class="dim"':""}>${rows[r][k]==null?"··":NTHEX.hx(rows[r][k])}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
    $("out").innerHTML=html}
  $("go").onclick=show;
  $("fix").onclick=()=>{$("in").value=$("in").value.split(/\r?\n/).map(l=>{const t=l.trim(),r=NTHEX.parse(t);return r.ok?NTHEX.make(r.addr,r.data,r.type):l}).join("\n");show()};
  $("ex").onchange=()=>{$("in").value=cfg.samples[+$("ex").value][1];show()};
  $("in").value=cfg.samples[0][1];show()}
