/* Bài 10 · Chương trình được tạo và chạy thế nào (FND-010) — sinh bởi tools/author/nentang/m10.py, không sửa tay.
   Bảng bit tương tác, phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeNtHex(document.getElementById("hex-l10"),{"id": "l10", "samples": [["Dòng HEX của Ví dụ 1 (sdld)", ":0D0000007590F012000880F87FFADFFE22F4\n:00000001FF"], ["Bản mới MOV P\u0031,#0FH", ":0D00000075900F12000880F87FFADFFE22D5\n:00000001FF"], ["Dòng bị hỏng (Ví dụ 8)", ":0D0000007590F012000880F87FFADFFE25F4"], ["Tự gõ: thiếu tổng kiểm tra", ":0300100075900F00"], ["Sai số byte", ":0400000075900F12"]]});
makeMtLab(document.getElementById("lab-l10"),{id:"l10",scenarios:[{"label": "Ví dụ: Theo dự án qua bảy chặng", "note": "Mỗi chặng tạo ra một loại file; ô viền xanh lá là chặng đã qua.", "steps": [{"t": "Bảy chặng từ chữ tới chip chạy", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div>", "say": "<p>Ô xanh là chặng đang xét, ô viền xanh lá là chặng đã qua. Dưới mỗi chặng ghi tên công cụ của Keil (A51, BL51) và của SDCC (sdas8051, sdld) dùng để kiểm chứng bài.<\/p>"}, {"t": "Dịch: mỗi file nguồn thành một file object", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">File<\/th><th scope=\"col\">Kích thước (byte)<\/th><\/tr><\/thead><tbody><tr><td>main.s (nguồn sdas8051)<\/td><td>228<\/td><\/tr><tr><td>main.rel (object)<\/td><td>198<\/td><\/tr><\/tbody><\/table>", "say": "<p>File object chứa mã máy, nhưng chỗ nào dùng tên ở file khác (DELAY) thì còn để trống kèm ghi chú “cần sửa”.<\/p>"}, {"t": "Liên kết: ghép object, định địa chỉ", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><p class=\"mt-calc\">main: 0000H…0007H (8 byte) · delay: 0008H…000CH (5 byte)<\/p>", "ask": {"q": "main dài 8 byte và nằm từ 0000H. Trình liên kết đặt DELAY ở đâu?", "o": ["0008H", "0000H", "0100H"], "a": 0}}, {"t": "Chuyển sang HEX: 13 byte ảnh mã máy → 50 ký tự", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p><p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">00<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">01<\/span><span class=\"f4\"><\/span><span class=\"f5 ok\">FF<\/span><\/p>", "say": "<p>File HEX là văn bản: mỗi byte viết bằng 2 chữ số, kèm địa chỉ và tổng kiểm tra. 13 byte mã máy thành file 50 ký tự (kể cả xuống dòng).<\/p>"}, {"t": "Nạp rồi reset: CPU đọc byte đầu ở 0000H", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div>", "say": "<p>Ví dụ 5 chạy file này trên ucsim s51 từ reset.<\/p>"}]}, {"label": "Ví dụ: Listing và object trước liên kết", "note": "LCALL DELAY còn 12 00 00; file object ghi chỗ cần sửa.", "steps": [{"t": "Listing của main trước liên kết", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Keil A51<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>75 90 F0<\/td><td>START: MOV P\u0031,#0F0H<\/td><\/tr><tr><td>0003H<\/td><td class=\"new\">12 00 00<\/td><td>LCALL DELAY<\/td><\/tr><tr><td>0006H<\/td><td>80 F8<\/td><td>SJMP START<\/td><\/tr><\/tbody><\/table>", "say": "<p>File listing (.LST) do trình dịch in ra: mỗi dòng nguồn kèm địa chỉ và byte mã máy. Người đọc dùng nó để kiểm tra lệnh dịch ra gì.<\/p>"}, {"t": "LCALL DELAY = 12 00 00: địa chỉ chưa biết", "html": "<p class=\"mt-calc\">12H = opcode LCALL · <b>00 00<\/b> = chỗ để trống<\/p><div class=\"n3-code\"><span class=\"n3-l\"><b>1<\/b><code>M main<\/code><\/span><span class=\"n3-l\"><b>2<\/b><code>S delay Ref000000<\/code><\/span><span class=\"n3-l\"><b>3<\/b><code>S .__.ABS. Def000000<\/code><\/span><span class=\"n3-l\"><b>4<\/b><code>T 00 00 00 75 90 F0 12 00 00 80 F8<\/code><\/span><span class=\"n3-l\"><b>5<\/b><code>R 00 00 00 01 02 07 00 00<\/code><\/span><\/div>", "ask": {"q": "Trong file object main.rel, dòng “S delay Ref000000” nghĩa là gì?", "o": ["delay nằm ở địa chỉ 0000H", "delay là tên được dùng nhưng định nghĩa ở nơi khác", "delay là một lỗi dịch"], "a": 1}, "say": "<p>Dòng S ghi bảng ký hiệu: Ref = tham chiếu tới tên ngoài, Def = định nghĩa. Dòng T là byte mã máy; dòng R ghi chỗ cần trình liên kết sửa. Đây là định dạng object của SDCC (ASxxxx); Keil dùng định dạng OMF-51 khác nhưng cùng ý.<\/p>"}]}, {"label": "Ví dụ: Liên kết điền địa chỉ DELAY", "note": "So listing trước và sau liên kết; đọc file map.", "steps": [{"t": "delay.rel định nghĩa delay", "html": "<div class=\"n3-code\"><span class=\"n3-l\"><b>1<\/b><code>S .__.ABS. Def000000<\/code><\/span><span class=\"n3-l\"><b>2<\/b><code>S delay Def000000<\/code><\/span><span class=\"n3-l\"><b>3<\/b><code>T 00 00 00 7F FA DF FE 22<\/code><\/span><\/div>"}, {"t": "Sau liên kết: LCALL = 12 00 08", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">Byte<\/th><th scope=\"col\">Keil A51<\/th><\/tr><\/thead><tbody><tr><td>0000H<\/td><td>75 90 F0<\/td><td>START: MOV P\u0031,#0F0H<\/td><\/tr><tr><td>0003H<\/td><td class=\"new\">12 00 08<\/td><td>LCALL DELAY<\/td><\/tr><tr><td>0006H<\/td><td>80 F8<\/td><td>SJMP START<\/td><\/tr><tr><td class=\"new\">0008H<\/td><td>7F FA<\/td><td>DELAY: MOV R7,#250<\/td><\/tr><tr><td>000AH<\/td><td>DF FE<\/td><td>LOOP: DJNZ R7,LOOP<\/td><\/tr><tr><td>000CH<\/td><td>22<\/td><td>RET<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Hai byte địa chỉ của LCALL sau liên kết là gì, theo thứ tự?", "o": ["08H rồi 00H", "00H rồi 00H", "00H rồi 08H"], "a": 2}, "say": "<p>Listing sau liên kết (.rst của sdld) có địa chỉ thật. LCALL ghi byte cao trước, giống MOV DPTR ở Bài 1.<\/p>"}, {"t": "File map ghi địa chỉ mọi tên", "html": "<p class=\"mt-calc\">prog.map: CSEG 00000000, size 0000000D (13 byte) · delay = <b>00000008<\/b><\/p>", "say": "<p>File map (.M51 của Keil, .map của sdld) liệt kê đoạn nào nằm ở đâu và địa chỉ của từng tên toàn cục. Khi chương trình nhảy sai chỗ, đây là file đầu tiên cần mở.<\/p>"}]}, {"label": "Ví dụ: Giải mã một dòng Intel HEX", "note": "Tô màu từng trường; tính tổng kiểm tra bằng bù hai.", "steps": [{"t": "Một bản ghi Intel HEX", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p>", "say": "<p>Mỗi dòng: dấu “:”, LL (số byte dữ liệu), AAAA (địa chỉ), TT (loại), dữ liệu, CC (tổng kiểm tra). Mọi trường viết bằng chữ số hex.<\/p>"}, {"t": "LL: 0D = 13 byte dữ liệu", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\" style=\"outline:2px solid var(--accent)\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p><p class=\"mt-calc\">0D = 13 byte dữ liệu<\/p>", "ask": {"q": "LL = 0DH. Dòng này chứa bao nhiêu byte dữ liệu?", "o": ["13", "0", "16"], "a": 0}}, {"t": "AAAA: 0000", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\" style=\"outline:2px solid var(--accent)\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p><p class=\"mt-calc\">0000: nạp từ địa chỉ 0000H<\/p>"}, {"t": "TT: 00", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\" style=\"outline:2px solid var(--accent)\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p><p class=\"mt-calc\">00: bản ghi dữ liệu<\/p>"}, {"t": "DD: 13 byte mã máy", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\" style=\"outline:2px solid var(--accent)\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p><p class=\"mt-calc\">75 90 F0 12 00 08 80 F8 7F FA DF FE 22<\/p>"}, {"t": "Tổng kiểm tra: tổng các byte rồi lấy bù hai", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\" style=\"outline:2px solid var(--accent)\">F4<\/span><\/p><p class=\"mt-calc\">0D + 00 + 00 + 00 + 75 + 90 + F0 + 12 + 00 + 08 + 80 + F8 + 7F + FA + DF + FE + 22 → 8 bit thấp = <b>0CH<\/b><\/p><p class=\"mt-calc\">100H − 0CH = <b>F4H<\/b> = byte CC ✓<\/p>", "say": "<p>Bộ đọc HEX cộng mọi byte của dòng kể cả CC: kết quả 8 bit thấp phải bằng 00H. Sai một chữ số là phát hiện được. Đây là bù hai đã học ở Chương 1.<\/p>"}, {"t": "Bản ghi kết thúc :00000001FF", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">00<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">01<\/span><span class=\"f4\"><\/span><span class=\"f5 ok\">FF<\/span><\/p>", "say": "<p>Loại 01: hết tệp, không có dữ liệu. File lớn hơn 64 KiB dùng thêm bản ghi loại 02 hoặc 04 để mở rộng địa chỉ (không gặp với 8051 64 KiB).<\/p>"}]}, {"label": "Ví dụ: Reset rồi chạy file vừa nạp (s51)", "note": "PC, SP, P\u0031 sau từng lệnh trên ucsim s51.", "steps": [{"t": "Reset: PC = 0000H, P\u0031 = FFH", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>PC<\/td><td>0000H<\/td><\/tr><tr><td>SP<\/td><td>07H<\/td><\/tr><tr><td>P\u0031<\/td><td>FFH<\/td><\/tr><\/tbody><\/table>", "say": "<p>Sau reset 8051 đặt PC = 0000H, SP = 07H, các cổng = FFH (Bài 1). Lệnh đầu tiên là byte ở 0000H của file vừa nạp.<\/p>"}, {"t": "MOV P\u0031,#0F0H: PC = 0003H, P\u0031 = F0H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>PC<\/td><td class=\"new\">0003H<\/td><\/tr><tr><td>SP<\/td><td>07H<\/td><\/tr><tr><td>P\u0031<\/td><td class=\"new\">F0H<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "MOV P\u0031,#0F0H dài 3 byte, bắt đầu ở 0000H. PC tiếp theo là?", "o": ["0001H", "0003H", "0008H"], "a": 1}}, {"t": "LCALL 0008H: PC = 0008H, SP = 09H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi / ô<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>PC<\/td><td class=\"new\">0008H<\/td><\/tr><tr><td>SP<\/td><td>09H<\/td><\/tr><tr><td>RAM 08H 09H<\/td><td class=\"new\">06 00<\/td><\/tr><\/tbody><\/table>", "say": "<p>LCALL cất địa chỉ lệnh kế tiếp (0006H, byte thấp 06H trước) rồi nhảy tới DELAY. Địa chỉ 0008H chính là số trình liên kết đã điền.<\/p>"}, {"t": "RET: quay lại PC = 0006H, SP = 07H", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>PC<\/td><td class=\"new\">0006H<\/td><\/tr><tr><td>SP<\/td><td>07H<\/td><\/tr><\/tbody><\/table>", "say": "<p>Số liệu đọc từ ucsim s51 chạy đúng file prog.ihx ở Ví dụ 1 (sau 250 lần DJNZ). Lệnh ở 0006H là SJMP START: chương trình lặp mãi.<\/p>"}]}, {"label": "Lỗi: Lỗi dịch (thiếu dấu phẩy)", "note": "Thông báo thật của sdas8051 chỉ ra file và dòng.", "steps": [{"t": "Dòng nguồn MOV A #5", "html": "<div class=\"n3-code\"><span class=\"n3-l\"><b>1<\/b><code>        CSEG    AT 0000H<\/code><\/span><span class=\"n3-l\"><b>2<\/b><code>START:  MOV     A #5                    ; sai: phải là MOV A,#5<\/code><\/span><span class=\"n3-l\"><b>3<\/b><code>        MOV     P\u0031,A<\/code><\/span><span class=\"n3-l\"><b>4<\/b><code>        END<\/code><\/span><\/div>", "say": "<p>Thiếu dấu phẩy giữa hai toán hạng.<\/p>"}, {"t": "Trình dịch báo lỗi, không tạo object", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><p class=\"mt-calc\">err.s:3: Error: &lt;q&gt; missing or improper operators, terminators, or delimiters<\/p>", "ask": {"q": "Có tạo được file object (và HEX) không?", "o": ["Có, chỉ bỏ dòng lỗi", "Có, lỗi chỉ hiện khi chạy", "Không: dừng ngay ở bước dịch"], "a": 2}, "say": "<p>Thông báo chép từ lần chạy thật của sdas8051 (dòng tương đương <code>mov a #5<\/code>): có tên file và số dòng 3. Keil A51 chưa được chạy (PENDING), câu chữ của mỗi trình dịch khác nhau nhưng đều chỉ ra dòng.<\/p>"}, {"t": "Sửa: MOV A,#5", "html": "<p class=\"mt-calc\">MOV A<b>,<\/b>#5 → 74H 05H<\/p>", "say": "<p>Đọc thông báo từ dòng đầu tiên, sửa đúng dòng được chỉ, dịch lại. Một lỗi cú pháp có thể kéo theo nhiều thông báo ở các dòng sau.<\/p>"}]}, {"label": "Lỗi: Lỗi liên kết (thiếu module delay)", "note": "Thông báo thật của sdld; không có file HEX.", "steps": [{"t": "main dịch được, nhưng quên thêm delay vào dự án", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">File dịch<\/th><th scope=\"col\">Kết quả<\/th><\/tr><\/thead><tbody><tr><td>main.a51 → main.rel<\/td><td>đạt<\/td><\/tr><tr><td>delay.a51<\/td><td class=\"bad\">không có trong dự án<\/td><\/tr><\/tbody><\/table>"}, {"t": "Trình liên kết không tìm thấy delay", "html": "<p class=\"mt-calc\">?ASlink-Warning-Undefined Global 'delay' referenced by module 'main'<\/p>", "ask": {"q": "Lỗi này thuộc bước nào?", "o": ["Liên kết", "Dịch", "Nạp"], "a": 0}, "say": "<p>Thông báo chép từ sdld. Không có file HEX nào được tạo (mã thoát khác 0). Trường hợp ngược lại, hai module cùng định nghĩa delay, sdld báo: <code>Multiple definition of delay<\/code>.<\/p>"}, {"t": "Sửa: thêm delay.a51 vào dự án", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Nguồn<\/b><small>main.a51, delay.a51 (chữ)<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình dịch<\/b><small>A51 · sdas8051<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Object<\/b><small>.OBJ · .rel: mã máy + tên chưa có địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Trình liên kết<\/b><small>BL51 · sdld: ghép, định địa chỉ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>HEX / BIN<\/b><small>.HEX: văn bản; .BIN: ảnh byte<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Nạp<\/b><small>bộ nạp ghi vào flash<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Chạy<\/b><small>reset: PC = 0000H<\/small><\/div><\/div><p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p>", "say": "<p>Trong Keil µVision là thêm file vào nhóm Source của project; với SDCC là ghi thêm delay.rel trên dòng lệnh sdld.<\/p>"}]}, {"label": "Bẫy: Tổng kiểm tra không khớp", "note": "Một chữ số đổi là bộ đọc HEX phát hiện.", "steps": [{"t": "Một chữ số bị đổi khi chép file", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\" style=\"outline:2px solid var(--accent)\">7590F012000880F87FFADFFE25<\/span><span class=\"f5\">F4<\/span><\/p><p class=\"mt-calc\">…DF FE <b>25<\/b> F4 (đúng là …DF FE 22 F4)<\/p>", "say": "<p>Giả định: file bị sửa nhầm khi chép tay hoặc khi truyền. Byte cuối của dữ liệu 22H (RET) thành 25H.<\/p>"}, {"t": "Cộng lại: tổng không còn bằng 00H", "html": "<p class=\"mt-calc\">tổng 8 bit của LL…DD = 0FH → bù hai = <b>F1H<\/b> ≠ F4H<\/p>", "ask": {"q": "Bộ đọc HEX kết luận gì?", "o": ["Dòng đúng, chỉ khác dữ liệu", "Dòng này hỏng: tổng kiểm tra không khớp", "Bản ghi kết thúc tệp"], "a": 1}, "say": "<p>Thử bằng công cụ đọc HEX ở mục 10.3: dán dòng này, trang báo tổng kiểm tra sai.<\/p>"}]}, {"label": "Bẫy: Sửa nguồn nhưng nạp file HEX cũ", "note": "Chip chạy đúng file được nạp, không phải file nguồn đang mở.", "steps": [{"t": "Phiên bản 1 đã build và nạp: P\u0031 = F0H", "html": "<p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">7590F012000880F87FFADFFE22<\/span><span class=\"f5 ok\">F4<\/span><\/p>", "say": "<p>Chip chạy đúng file này.<\/p>"}, {"t": "Sửa nguồn thành MOV P\u0031,#0FH", "html": "<p class=\"mt-calc\">START: MOV P\u0031,#<b>0FH<\/b><\/p><p class=\"n3-hexline\"><span class=\"f0\">:<\/span><span class=\"f1\">0D<\/span><span class=\"f2\">0000<\/span><span class=\"f3\">00<\/span><span class=\"f4\">75900F12000880F87FFADFFE22<\/span><span class=\"f5 ok\">D5<\/span><\/p>", "ask": {"q": "Chưa build lại, chỉ bấm nạp. Chip xuất gì ra P\u0031?", "o": ["0FH", "Không chạy", "F0H (file HEX cũ)"], "a": 2}, "say": "<p>Dòng HEX của bản mới (build thật) chỉ khác byte thứ ba (0FH thay F0H) và tổng kiểm tra (D5H thay F4H).<\/p>"}, {"t": "Cách tránh: build lại, kiểm tra ngày giờ và nội dung file HEX", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Phiên bản<\/th><th scope=\"col\">Byte thứ 3<\/th><th scope=\"col\">CC<\/th><\/tr><\/thead><tbody><tr><td>cũ (đang nạp)<\/td><td class=\"bad\">F0<\/td><td>F4<\/td><\/tr><tr><td>mới<\/td><td>0F<\/td><td>D5<\/td><\/tr><\/tbody><\/table>", "say": "<p>Ghi vào phiếu lab tên và thời điểm của file đã nạp (Bài 12). Luôn build lại ngay trước khi nạp; khi kết quả lạ, mở file HEX hoặc listing để đối chiếu byte.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l10"),"l10",[{"kind": "order", "t": "Sắp xếp chuỗi build và nạp", "items": ["Viết mã nguồn main.a51 và delay.a51", "Trình dịch hợp ngữ dịch từng file thành file object (mã máy chưa có địa chỉ cuối của tên ngoài)", "Trình liên kết ghép các object, chọn địa chỉ cho từng đoạn và điền địa chỉ của DELAY", "Chuyển ảnh mã máy tuyệt đối thành file Intel HEX", "Phần mềm nạp đọc file HEX, kiểm tra tổng kiểm tra từng dòng và ghi vào bộ nhớ chương trình", "Reset: 8051 bắt đầu đọc lệnh ở địa chỉ 0000H"], "hints": ["File object ra đời trước khi biết địa chỉ của hàm nằm ở file khác.", "Chỉ trình liên kết thấy mọi module cùng lúc, nên nó mới điền được địa chỉ thật.", "File HEX là thứ được nạp; chip chỉ chạy sau khi được nạp và reset."], "why": "Nguồn → (dịch) object → (liên kết, định vị) ảnh mã máy tuyệt đối → (chuyển đổi) HEX → (nạp, kiểm tra tổng) bộ nhớ chương trình → reset, PC = 0000H. Trong lần chạy thật: main.rel còn LCALL 12 00 00, sau sdld thành 12 00 08.", "d": "<p>Dự án có hai file nguồn main.a51 và delay.a51 (Ví dụ 1–3). Đưa các bước về đúng thứ tự từ trên xuống bằng nút ↑ ↓.<\/p>"}, {"kind": "base", "t": "Giải mã bản ghi Intel HEX", "items": [{"q": "Bản ghi :0D 0000 00 7590F012000880F8 7FFADFFE22 F4 — số byte dữ liệu (LL)", "f": "dec", "a": 13}, {"q": "Cùng bản ghi — địa chỉ nạp (AAAA)", "f": "hex", "a": 0}, {"q": "Cùng bản ghi — loại bản ghi (TT)", "f": "dec", "a": 0}, {"q": "Cùng bản ghi — địa chỉ của DELAY mà LCALL (byte 12H) gọi tới", "f": "hex", "a": 8}, {"q": "Cùng bản ghi — byte tổng kiểm tra (CC)", "f": "hex", "a": 244}, {"q": "Tính byte tổng kiểm tra cho bản ghi :03 0010 00 75900F ??", "f": "hex", "a": 217}, {"q": "Byte tổng kiểm tra của bản ghi kết thúc :00 0000 01 ??", "f": "hex", "a": 255}], "hints": ["Cắt bản ghi thành từng cặp chữ số: ':' LL AAAA TT dữ liệu CC.", "LCALL addr16 dài 3 byte: 12H rồi byte cao, byte thấp của địa chỉ.", "Tổng kiểm tra: cộng mọi byte từ LL tới hết dữ liệu, lấy 8 bit thấp, rồi lấy bù hai (256 − tổng, nếu tổng khác 0)."], "why": "0D = 13 byte, ở 0000H, loại 00 (dữ liệu); byte 4–6 là 12 00 08: LCALL 0008H; CC = F4H. Bản ghi mới: 03 + 00 + 10 + 00 + 75 + 90 + 0F = 127H → 8 bit thấp 27H → 100H − 27H = D9H. Bản ghi kết thúc: 00 + 00 + 00 + 01 = 01H → FFH.", "d": "<p>Bản ghi Intel HEX có dạng <code>:LL AAAA TT dữ liệu CC<\/code> (viết liền, dấu cách chỉ để dễ đọc). Trả lời theo hệ ghi cạnh ô; hex viết 0D, 0DH hay 0x0D đều được.<\/p>"}, {"kind": "pick", "t": "Lỗi xảy ra ở bước nào", "cats": ["Lỗi dịch", "Lỗi liên kết", "Lỗi nạp (file HEX)", "Lỗi khi chạy"], "items": [{"q": "MOV A #5 (thiếu dấu phẩy)", "a": 0}, {"q": "Undefined Global 'delay' referenced by module 'main'", "a": 1}, {"q": "Một dòng của file .hex có tổng kiểm tra không khớp", "a": 2}, {"q": "LED nháy nhanh gấp đôi dự kiến vì tính sai số vòng trễ", "a": 3}, {"q": "Hai module cùng khai báo PUBLIC DELAY: Multiple definition of delay", "a": 1}, {"q": "Viết MOV A,#FFH (thiếu số 0 đứng đầu, Bài 1)", "a": 0}, {"q": "Sửa nguồn thành MOV P\u0031,#0FH nhưng nạp lại file HEX cũ: P\u0031 vẫn ra F0H", "a": 2}, {"q": "Viết MOV A,30H khi muốn nạp hằng 30H (thiếu #, Bài 1)", "a": 3}], "hints": ["Lỗi dịch: trình dịch không hiểu một dòng; không có file object.", "Lỗi liên kết: từng file dịch được nhưng ghép lại thì thiếu hoặc thừa một tên.", "Lỗi khi chạy: mọi bước build đều qua nhưng chương trình làm sai việc; lỗi nạp: chip không nhận đúng file mới nhất."], "why": "Thiếu dấu phẩy là lỗi cú pháp, báo khi dịch. FFH bị hiểu là tên chưa định nghĩa: sdas8051 dịch theo mặc định báo ngay (undefined symbol); nếu dịch với tùy chọn -g, tên lạ được coi là tên ngoài và lỗi dời sang bước liên kết. Tên ngoài không có định nghĩa, hoặc có hai định nghĩa, chỉ lộ ra khi sdld ghép module. Tổng kiểm tra sai và file HEX cũ là chuyện của bước nạp. Vòng trễ tính sai và thiếu # dịch, liên kết, nạp đều đạt nhưng chạy sai.", "d": "<p>Mỗi dòng là một triệu chứng hoặc thông báo. Chọn bước của chuỗi build và nạp mà lỗi đó lộ ra.<\/p>"}]);

makeQuiz("quiz10","score10",[{"q": "Listing của main (trước liên kết) ghi LCALL DELAY = 12 00 00. Vì sao hai byte địa chỉ là 00 00?", "o": ["DELAY nằm ở địa chỉ 0000H trong bộ nhớ chương trình", "Trình dịch đã báo lỗi nên ghi tạm 00 00 vào chỗ đó", "Trình dịch chưa biết địa chỉ của DELAY; trình liên kết điền sau", "LCALL của 8051 luôn gọi tới địa chỉ 0000H rồi tự nhảy tiếp"], "a": 2, "e": "DELAY ở module khác (EXTRN), nên file object chỉ ghi chỗ cần sửa và tên ký hiệu. Sau khi sdld ghép main (8 byte) với delay, DELAY ở 0008H và lệnh thành 12 00 08. Không có lỗi nào; LCALL gọi đúng địa chỉ 16 bit ghi trong lệnh."}, {"q": "Phần mềm nạp lấy ảnh mã máy để ghi vào bộ nhớ chương trình của 8051 từ file nào?", "o": ["File object (.OBJ / .rel) của từng module", "File listing (.LST)", "File nguồn (.A51)", "File HEX tạo ra sau khi liên kết"], "a": 3, "e": "Chỉ file sau liên kết mới có địa chỉ tuyệt đối của mọi lệnh; file HEX là dạng văn bản của ảnh đó. Object còn thiếu địa chỉ của tên ngoài; listing để người đọc; file nguồn là chữ, chip không chạy được."}, {"q": "Bản ghi Intel HEX :020000007400?? (2 byte 74H 00H ở 0000H). Byte tổng kiểm tra là gì?", "o": ["76H", "8AH", "89H", "8BH"], "a": 1, "e": "Tổng 02 + 00 + 00 + 00 + 74 + 00 = 76H; bù hai: 100H − 76H = 8AH. 76H là quên lấy bù; 89H là bù một (đảo bit) mà quên cộng 1; 8BH là cộng thừa 1."}, {"q": "Sau khi nạp và reset, 8051 bắt đầu đọc lệnh ở địa chỉ nào?", "o": ["0003H", "0000H", "0100H", "FFFF0H"], "a": 1, "e": "Reset đặt PC của 8051 về 0000H (s51: lệnh đầu tiên chạy là byte 75H ở 0000H). 0003H là vector ngắt ngoài 0 (khóa 8051); 0100H là chỗ DOS nạp file .COM của 8086; FFFF0H là địa chỉ khởi động của 8086."}, {"q": "Thông báo “Undefined Global 'delay' referenced by module 'main'” xuất hiện ở bước nào?", "o": ["Liên kết", "Dịch hợp ngữ", "Nạp file HEX", "Chạy chương trình"], "a": 0, "e": "Từng file dịch được (main.rel chỉ ghi delay là tham chiếu ngoài). Khi sdld ghép mà không có module nào định nghĩa delay thì báo lỗi này và không tạo được file HEX."}]);

